(7713026, 1267830, 100831, '<td valign="top">I see the smile.</td>', 'I see the smile.', '2022-01-28 10:10:18.000000', NULL, 1),
(7713027, 1267807, 100831, '<td valign="top">Two for the price of one! Good thinking and well done.</td>', 'Two for the price of one! Good thinking and well done.', '2022-01-28 10:11:14.000000', NULL, 1),
(7713029, 1267813, 103142, '<td valign="top">I like the shot -- It''s very interesting, but he certainly doesn''t look happy... ?</td>', 'I like the shot -- It''s very interesting, but he certainly doesn''t look happy... ?', '2022-01-28 10:54:26.000000', NULL, 1),
(7713031, 1267808, 103142, '<td valign="top">The photo is rather nice, but I guess I don''t see what it has to do with Anniversary... I think I''m missing something.</td>', 'The photo is rather nice, but I guess I don''t see what it has to do with Anniversary... I think I''m missing something.', '2022-01-28 11:16:45.000000', NULL, 1),
(7713035, 1267631, 103142, '<td valign="top">I like the lines of ribbons a lot. But I''m confused by the yellow splotches in the white areas. I don''t know if it''s meant to be an overlay, or what. But it makes it look kind of dirty. :(  Cool design, but that background makes it unappealing, imo. sorry!</td>', 'I like the lines of ribbons a lot. But I''m confused by the yellow splotches in the white areas. I don''t know if it''s meant to be an overlay, or what. But it makes it look kind of dirty. :(  Cool design, but that background makes it unappealing, imo. sorry!', '2022-01-28 11:22:15.000000', NULL, 1),
(7713037, 1267829, 103142, '<td valign="top">Congrats on the 150 years! I''m never sure about astrophotography and whether or not stars should be blue. I''m curious if this would have been better with some color correction? Or perhaps in B&amp;W? (although, I do like the warmth and colors of the stones)</td>', 'Congrats on the 150 years! I''m never sure about astrophotography and whether or not stars should be blue. I''m curious if this would have been better with some color correction? Or perhaps in B&W? (although, I do like the warmth and colors of the stones)', '2022-01-28 11:25:44.000000', NULL, 1),
(7713042, 1267683, 103142, '<td valign="top">So I''m voting on whether I like the photo, and giving a +1 or +2 for meeting the challenge. Very cool shot. -8- from me -- though I do want to know: Did you have to clone out a car to get 20? ;P</td>', 'So I''m voting on whether I like the photo, and giving a +1 or +2 for meeting the challenge. Very cool shot. -8- from me -- though I do want to know: Did you have to clone out a car to get 20? ;P', '2022-01-28 13:51:56.000000', NULL, 1),
